written_at.fn_text:
export async function updateWorkspaceSettingsAction(
  currentSlug: string,
  _prevState: ActionState,
  formData: FormData
): Promise<ActionState> {
  const { workspace } = await requireWorkspaceAdmin(currentSlug);

  const parsed = workspaceSettingsSchema.safeParse({
    name: formData.get("name"),
    slug: formData.get("slug"),
    webhookUrl: formData.get("webhookUrl") ?? "",
    slackSigningSecret: formData.get("slackSigningSecret") ?? "",
  });

  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid input" };
  }

  const { name, slug, webhookUrl, slackSigningSecret } = parsed.data;

  if (slug !== workspace.slug) {
    const slugTaken = await prisma.workspace.findUnique({ where: { slug } });
    if (slugTaken) {
      return { error: "That slug is already taken" };
    }
  }

  await prisma.workspace.update({
    where: { id: workspace.id },
    data: { name, slug, webhookUrl: webhookUrl ?? null, slackSigningSecret: slackSigningSecret ?? null },
  });

  if (slug !== workspace.slug) {
    redirect(`/w/${slug}/settings?saved=1`);
  }

  revalidatePath(`/w/${slug}/settings`);
  return {};
}

